import json

ENCODING = "utf-8"


def encode(kind, **fields):
    """One JSON object per line, ready to send over a socket."""
    return (json.dumps({"type": kind, **fields}) + "\n").encode(ENCODING)


def decode(line):
    data = json.loads(line.decode(ENCODING))
    if not isinstance(data, dict) or "type" not in data:
        raise ValueError("message needs a type")
    return data

import unittest

from chat.protocol import decode, encode


class ProtocolTests(unittest.TestCase):
    def test_round_trip(self):
        data = encode("say", nick="ana", text="héllo")
        self.assertTrue(data.endswith(b"\n"))
        self.assertEqual(decode(data), {"type": "say", "nick": "ana", "text": "héllo"})

    def test_rejects_non_json(self):
        with self.assertRaises(ValueError):
            decode(b"nope\n")

    def test_requires_type(self):
        with self.assertRaises(ValueError):
            decode(b'{"text": "hi"}\n')


if __name__ == "__main__":
    unittest.main()

import socket
import threading

from .protocol import decode, encode


class ChatServer:
    def __init__(self, host="127.0.0.1", port=0):
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.sock.bind((host, port))
        self.sock.listen()
        self.address = self.sock.getsockname()
        self.clients = {}            # nickname -> socket
        self.lock = threading.Lock()
        self.running = False

    def start(self):
        self.running = True
        threading.Thread(target=self._accept_loop, daemon=True).start()
        return self.address

    def stop(self):
        self.running = False
        with self.lock:
            for conn in list(self.clients.values()):
                self._close(conn)
            self.clients.clear()
        self.sock.close()

    def nicknames(self):
        with self.lock:
            return sorted(self.clients)

    def broadcast(self, kind, **fields):
        data = encode(kind, **fields)
        with self.lock:
            targets = list(self.clients.values())
        for conn in targets:
            try:
                conn.sendall(data)
            except OSError:
                pass

    def _accept_loop(self):
        while self.running:
            try:
                conn, _ = self.sock.accept()
            except OSError:
                break
            threading.Thread(target=self._serve, args=(conn,), daemon=True).start()

    def _serve(self, conn):
        reader = conn.makefile("rb")
        nick = None
        try:
            for line in reader:
                try:
                    msg = decode(line)
                except ValueError:
                    self._send(conn, "error", text="bad message")
                    continue
                kind = msg["type"]
                if kind == "join" and nick is None:
                    nick = self._join(conn, str(msg.get("nick", "")).strip())
                elif nick is None:
                    self._send(conn, "error", text="join first")
                elif kind == "say":
                    self.broadcast("say", nick=nick, text=str(msg.get("text", ""))[:500])
                elif kind == "who":
                    self._send(conn, "who", nicks=self.nicknames())
                elif kind == "quit":
                    break
        except OSError:
            pass
        finally:
            self._leave(conn, nick)

    def _join(self, conn, nick):
        with self.lock:
            taken = not nick or nick in self.clients
            if not taken:
                self.clients[nick] = conn
        if taken:
            self._send(conn, "error", text="nickname unavailable")
            return None
        self._send(conn, "welcome", nick=nick)
        self.broadcast("notice", text=f"{nick} joined")
        return nick

    def _leave(self, conn, nick):
        if nick:
            self.broadcast("notice", text=f"{nick} left")
        self._close(conn)

    def _send(self, conn, kind, **fields):
        try:
            conn.sendall(encode(kind, **fields))
        except OSError:
            pass

    @staticmethod
    def _close(conn):
        try:
            conn.close()
        except OSError:
            pass

import queue
import socket
import threading

from .protocol import decode, encode


class ChatClient:
    def __init__(self, host, port, nick, timeout=3):
        self.nick = nick
        self.sock = socket.create_connection((host, port), timeout=timeout)
        self.sock.settimeout(None)
        self.inbox = queue.Queue()
        threading.Thread(target=self._read_loop, daemon=True).start()
        self._send("join", nick=nick)

    def _send(self, kind, **fields):
        self.sock.sendall(encode(kind, **fields))

    def say(self, text):
        self._send("say", text=text)

    def who(self):
        self._send("who")

    def quit(self):
        try:
            self._send("quit")
        except OSError:
            pass
        self.sock.close()

    def _read_loop(self):
        try:
            for line in self.sock.makefile("rb"):
                self.inbox.put(decode(line))
        except (OSError, ValueError):
            pass
        self.inbox.put({"type": "closed"})

    def next_message(self, timeout=2):
        try:
            return self.inbox.get(timeout=timeout)
        except queue.Empty:
            return None

    def wait_for(self, kind, timeout=2):
        """Skip messages until one of the given type arrives (None on timeout)."""
        while True:
            msg = self.next_message(timeout)
            if msg is None:
                return None
            if msg["type"] == kind:
                return msg
            if msg["type"] == "closed":
                return None

