import argparse
import threading

from .client import ChatClient
from .server import ChatServer


def serve(args):
    server = ChatServer(args.host, args.port)
    host, port = server.start()
    print(f"listening on {host}:{port} (Ctrl+C to stop)")
    try:
        threading.Event().wait()
    except KeyboardInterrupt:
        server.stop()


def show_messages(client):
    while True:
        msg = client.next_message(timeout=None)
        if msg["type"] == "closed":
            print("disconnected")
            break
        if msg["type"] == "say":
            print(f"<{msg['nick']}> {msg['text']}")
        elif msg["type"] == "who":
            print("online:", ", ".join(msg["nicks"]))
        else:
            print("*", msg.get("text", msg["type"]))


def join(args):
    client = ChatClient(args.host, args.port, args.nick)
    threading.Thread(target=show_messages, args=(client,), daemon=True).start()
    try:
        for line in iter(input, "/quit"):
            if line == "/who":
                client.who()
            else:
                client.say(line)
    except (EOFError, KeyboardInterrupt):
        pass
    client.quit()


def main():
    parser = argparse.ArgumentParser(prog="chat")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=9000)
    sub = parser.add_subparsers(dest="mode", required=True)
    sub.add_parser("serve")
    joiner = sub.add_parser("join")
    joiner.add_argument("nick")
    args = parser.parse_args()
    if args.mode == "serve":
        serve(args)
    else:
        join(args)


main()
